package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.content.res.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.*;
public class InterfaceLanguageTest extends Instrumentation {
    void check(boolean yes,String message){if(!yes)throw new AssertionError(message);}
    void ui(Runnable task){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{task.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    void await(java.util.function.BooleanSupplier test,String message)throws Exception{long end=SystemClock.elapsedRealtime()+35000;while(SystemClock.elapsedRealtime()<end){AtomicBoolean yes=new AtomicBoolean();ui(()->yes.set(test.getAsBoolean()));if(yes.get())return;Thread.sleep(60);}throw new AssertionError(message);}
    boolean hasText(View view,String text){if(view instanceof TextView&&text.equals(((TextView)view).getText().toString()))return true;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)if(hasText(((ViewGroup)view).getChildAt(i),text))return true;return false;}
    void screenshot(String name)throws Exception{waitForIdleSync();Thread.sleep(450);android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image!=null){try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),name))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}}
    void locale(String tag)throws Exception{ui(()->getTargetContext().getSystemService(LocaleManager.class).setApplicationLocales(LocaleList.forLanguageTags(tag)));Thread.sleep(450);}
    public void onCreate(Bundle b){super.onCreate(b);start();}
    public void onStart(){Bundle result=new Bundle();boolean passed=false;MainActivity reader=null;ShelfActivity shelf=null;Context target=getTargetContext();String original=target.getSystemService(LocaleManager.class).getApplicationLocales().toLanguageTags();android.content.SharedPreferences settings=target.getSharedPreferences("reading_settings",0);String readingLanguage=settings.getString("readingLanguage","");String voice=settings.getString("systemVoiceKey","");int offlineVoice=settings.getInt("offlineVoice",1000);float speed=settings.getFloat("rate",1f);try{
        String[] tags={"zh-Hans","zh-Hant","en","ja","ko","fr","de","es","pt","ru","ar","hi","id","vi","th"};String[] library={"书架","書架","Library","本棚","책장","Bibliothèque","Bibliothek","Biblioteca","Biblioteca","Библиотека","المكتبة","लाइब्रेरी","Rak buku","Kệ sách","ชั้นหนังสือ"};
        int validated=0;for(int i=0;i<tags.length;i++){Configuration config=new Configuration(target.getResources().getConfiguration());config.setLocales(LocaleList.forLanguageTags(tags[i]));Context translated=target.createConfigurationContext(config);check(library[i].equals(translated.getString(R.string.ui_157)),"wrong resources for "+tags[i]);for(java.lang.reflect.Field field:R.string.class.getFields())if(field.getName().startsWith("ui_")||field.getName().equals("interface_language")){String value=translated.getString(field.getInt(null));check(!value.trim().isEmpty(),"empty "+tags[i]+" "+field.getName());}validated++;}
        Configuration unsupported=new Configuration(target.getResources().getConfiguration());unsupported.setLocales(LocaleList.forLanguageTags("it"));check("Library".equals(target.createConfigurationContext(unsupported).getString(R.string.ui_157)),"unsupported locale does not fall back to English");Configuration traditional=new Configuration(unsupported);traditional.setLocales(LocaleList.forLanguageTags("zh-TW"));check("書架".equals(target.createConfigurationContext(traditional).getString(R.string.ui_157)),"traditional region fallback failed");
        for(String tag:new String[]{"en","ja","de","ar"}){locale(tag);shelf=(ShelfActivity)startActivitySync(new Intent(target,ShelfActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final ShelfActivity a=shelf;await(()->hasText(a.root,a.getString(R.string.ui_157)),"shelf did not translate "+tag);ui(()->check(a.root.getLayoutDirection()==("ar".equals(tag)?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR),"wrong layout direction "+tag));Thread.sleep(250);screenshot("language-shelf-"+tag+".png");ui(()->a.importPage());await(()->hasText(a.root,a.getString(R.string.ui_170)),"import page untranslated "+tag);screenshot("language-import-"+tag+".png");ui(()->a.finish());shelf=null;}
        locale("en");shelf=(ShelfActivity)startActivitySync(new Intent(target,ShelfActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final ShelfActivity importer=shelf;ui(()->{importer.importPage();ShelfActivity.Entry entry=new ShelfActivity.Entry(android.net.Uri.parse("content://locale-qa/book"),"original-title.txt",123,0);entry.selected=true;importer.files.add(entry);importer.search.setText("original");importer.renderFiles();});locale("ja");await(()->hasText(importer.root,importer.getString(R.string.ui_170)),"live import page locale did not change");ui(()->{check(!importer.dead&&importer.importing&&importer.files.size()==1&&importer.files.get(0).selected&&importer.query.equals("original"),"locale lost pending import selection");importer.finish();});shelf=null;
        locale("en");reader=(MainActivity)startActivitySync(new Intent(target,MainActivity.class).putExtra("book_id","interface_locale_qa").putExtra("book_name","原书名保持中文").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=reader;await(()->a.offlineReady&&a.system.initialized,"engines not ready");ui(()->{StringBuilder text=new StringBuilder("第一章 原文标题\n");for(int i=0;i<40;i++)text.append("书页轻轻翻动，风从窗边吹过。听书时界面语言不会改变书籍原文。\n");a.text=text.toString();a.chapters=MainActivity.parse(a.text);a.position=80;a.readingLanguage="";a.systemVoiceKey=a.system.offlineVoice("zh","").key;a.showPosition(true);a.startReading();});await(()->a.playing&&a.focusGeneration==a.generation,"speech not started");int generation=a.generation;String key=a.systemVoiceKey;locale("ar");await(()->"ar".equals(AppLanguage.locale(a).getLanguage())&&hasText(a.root,a.getString(R.string.ui_31)),"reader locale not refreshed");ui(()->{check(a.playing&&!a.destroyed&&a.generation==generation,"locale change restarted or stopped speech");check(key.equals(a.systemVoiceKey)&&a.readingLanguage.isEmpty(),"locale changed voice or reading language");check("原书名保持中文".contentEquals(a.title.getText()),"book name translated");check(a.content.getText().toString().contains("原文标题"),"source text changed");});screenshot("language-reader-ar.png");ui(()->{a.stop();a.directory();});await(()->a.chapterPicker!=null&&a.chapterPicker.isShowing(),"chapter sheet missing");ui(()->check(a.chapterPicker.search.getHint().toString().equals(a.getString(R.string.ui_4)),"chapter search untranslated"));screenshot("language-chapters-ar.png");ui(()->{a.chapterPicker.dismiss();a.chooseVoice();});await(()->a.voicePicker!=null&&a.voicePicker.isShowing(),"voice sheet missing");ui(()->check(a.voicePicker.tabs.get(0).getText().toString().equals(a.getString(R.string.ui_201)),"voice tabs untranslated"));screenshot("language-voices-ar.png");ui(()->a.voicePicker.dismiss());locale("ja");await(()->"ja".equals(AppLanguage.locale(a).getLanguage())&&hasText(a.root,a.getString(R.string.ui_31)),"Japanese reader not refreshed");screenshot("language-reader-ja.png");ui(()->{a.stop();a.finish();});reader=null;
        locale("");check(target.getSystemService(LocaleManager.class).getApplicationLocales().toLanguageTags().isEmpty(),"follow system was not cleared");shelf=(ShelfActivity)startActivitySync(new Intent(target,ShelfActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final ShelfActivity followed=shelf;Locale system=target.getSystemService(LocaleManager.class).getSystemLocales().get(0);check(AppLanguage.locale(followed).getLanguage().equals(system.getLanguage()),"follow system locale mismatch");check(settings.getString("readingLanguage","").equals(readingLanguage)&&settings.getString("systemVoiceKey","").equals(voice)&&settings.getInt("offlineVoice",1000)==offlineVoice&&settings.getFloat("rate",1f)==speed,"global speech preferences changed");result.putInt("validatedLanguages",validated);result.putString("result","PASS: all 15 language resources; unsupported English fallback; zh-TW traditional; live shelf/import EN JA DE AR; RTL; locale changes preserve active system speech and source text; localized chapter/voice sheets; follow system; speech preferences unchanged");passed=true;
    }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{if(reader!=null){final MainActivity a=reader;ui(()->{a.stop();a.finish();});}if(shelf!=null){final ShelfActivity a=shelf;ui(()->a.finish());}try{locale(original);}catch(Exception ignored){}target.getSharedPreferences("reader_interface_locale_qa",0).edit().clear().commit();new File(target.getFilesDir(),"book_interface_locale_qa.txt.position").delete();}finish(passed?-1:0,result);}
}
